          { at: 10, caption: "Nguyên tố có một nhiệt độ nóng chảy; đồng thau và đồng thanh nóng chảy trong một khoảng nhiệt độ", svg: "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 640 240' role='img' aria-label='Nhiệt độ nóng chảy của thiếc, kẽm, đồng và hai hợp kim của đồng' stroke='currentColor' fill='none' stroke-width='1.5' font-family='sans-serif' font-size='13'><line x1='140' y1='190' x2='610' y2='190' stroke-width='1.5'/><line x1='140' y1='190' x2='140' y2='196' stroke-width='1'/><text x='140' y='212' text-anchor='middle' font-size='11.5' fill='currentColor' stroke='none'>0</text><line x1='218.33333333333331' y1='190' x2='218.33333333333331' y2='196' stroke-width='1'/><text x='218.33333333333331' y='212' text-anchor='middle' font-size='11.5' fill='currentColor' stroke='none'>200</text><line x1='296.66666666666663' y1='190' x2='296.66666666666663' y2='196' stroke-width='1'/><text x='296.66666666666663' y='212' text-anchor='middle' font-size='11.5' fill='currentColor' stroke='none'>400</text><line x1='375' y1='190' x2='375' y2='196' stroke-width='1'/><text x='375' y='212' text-anchor='middle' font-size='11.5' fill='currentColor' stroke='none'>600</text><line x1='453.3333333333333' y1='190' x2='453.3333333333333' y2='196' stroke-width='1'/><text x='453.3333333333333' y='212' text-anchor='middle' font-size='11.5' fill='currentColor' stroke='none'>800</text><line x1='531.6666666666667' y1='190' x2='531.6666666666667' y2='196' stroke-width='1'/><text x='531.6666666666667' y='212' text-anchor='middle' font-size='11.5' fill='currentColor' stroke='none'>1000</text><line x1='610' y1='190' x2='610' y2='196' stroke-width='1'/><text x='610' y='212' text-anchor='middle' font-size='11.5' fill='currentColor' stroke='none'>1200</text><text x='375' y='230' text-anchor='middle' font-size='11.5' fill='currentColor' stroke='none'>nhiệt độ nóng chảy (°C)</text><text x='130' y='29' text-anchor='end' font-weight='bold' fill='currentColor' stroke='none'>thiếc</text><line x1='140' y1='24' x2='610' y2='24' stroke-width='0.6' stroke-opacity='0.25' stroke-dasharray='3 3'/><circle cx='230.86666666666667' cy='24' r='7' fill='#868e96' fill-opacity='0.7'/><text x='242.86666666666667' y='29' font-size='11.5' fill='currentColor' stroke='none'>232 °C</text><text x='130' y='61' text-anchor='end' font-weight='bold' fill='currentColor' stroke='none'>kẽm</text><line x1='140' y1='56' x2='610' y2='56' stroke-width='0.6' stroke-opacity='0.25' stroke-dasharray='3 3'/><circle cx='304.3041666666667' cy='56' r='7' fill='#868e96' fill-opacity='0.7'/><text x='316.3041666666667' y='61' font-size='11.5' fill='currentColor' stroke='none'>419,5 °C</text><text x='130' y='93' text-anchor='end' font-weight='bold' fill='currentColor' stroke='none'>đồng</text><line x1='140' y1='88' x2='610' y2='88' stroke-width='0.6' stroke-opacity='0.25' stroke-dasharray='3 3'/><circle cx='564.9583333333333' cy='88' r='7' fill='#868e96' fill-opacity='0.7'/><text x='552.9583333333333' y='93' text-anchor='end' font-size='11.5' fill='currentColor' stroke='none'>1085 °C</text><text x='130' y='125' text-anchor='end' font-weight='bold' fill='currentColor' stroke='none'>đồng thau</text><line x1='140' y1='120' x2='610' y2='120' stroke-width='0.6' stroke-opacity='0.25' stroke-dasharray='3 3'/><rect x='492.5' y='112' width='39.16666666666674' height='16' fill='#c9782a' fill-opacity='0.55' rx='8'/><text x='484.5' y='125' text-anchor='end' font-size='11.5' fill='currentColor' stroke='none'>900–1000 °C</text><text x='130' y='157' text-anchor='end' font-weight='bold' fill='currentColor' stroke='none'>đồng thanh</text><line x1='140' y1='152' x2='610' y2='152' stroke-width='0.6' stroke-opacity='0.25' stroke-dasharray='3 3'/><rect x='476.8333333333333' y='144' width='113.58333333333343' height='16' fill='#c9782a' fill-opacity='0.55' rx='8'/><text x='468.8333333333333' y='157' text-anchor='end' font-size='11.5' fill='currentColor' stroke='none'>860–1150 °C</text></svg>" }
